	"testing"
	"time"
)

// seedUsage 直接向台账写入带不同时区偏移的申请记录并保存，
// 模拟同一台机器在不同系统时区下先后留下的历史。
func seedUsage(t *testing.T, l *Ledger, recs ...UsageRecord) {
	t.Helper()
