			Allowed: false, Reasons: []string{"第一次"}},
		UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00+00:00",
			Allowed: true, Reasons: []string{}},
		UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T18:00:00+08:00",
