		{"M-1", "2026-10-05T10:00:00Z"},
		{"M-1", "2026-10-05T10:00:00+00:00"},
		{"M-1", "2026-10-05T18:00:00+08:00"},
		{"M-2", "2026-10-05T10:00:00Z"},
