308		withChanges.Changes = []PlanChange{{
309			From: "2026-10-20", To: "2026-11-05",
310			ChangedAt: "2026-10-07T09:00:00+08:00", Reason: "实验室排期冲突",
311		}}
312		seedPlans(t, l,
313			testPlan("PL-LATE", "M-1", "2026-10-06T02:00:00Z", PlanStatusDone),
