320		if got := planNumbers(plans); !reflect.DeepEqual(got, []string{"PL-EARLY", "PL-LATE"}) {
321			t.Fatalf("排序错误：%v", got)
322		}
323		p0 := plans[0]
324		if p0.OriginalDate != "2026-10-20" || p0.PlannedDate != "2026-11-05" ||
325			len(p0.Changes) != 1 || p0.Changes[0].Reason != "实验室排期冲突" ||
326			p0.Changes[0].ChangedAt != "2026-10-07T09:00:00+08:00" {
327			t.Fatalf("改期历史或计划日期未被原样保留：%+v", p0)
