// 单独参与排列、不因时间相同而被合并。
func sortHistoryByTime[T any](items []T, timeText func(T) string, tieBefore func(a, b T) bool) {
	keys := make([]historyTimeKey, len(items))
	for i, it := range items {
		keys[i] = parseHistoryTimeKey(timeText(it))
	}
	sort.SliceStable(items, func(i, j int) bool {
		if c := compareHistoryTime(keys[i], keys[j]); c != 0 {
			return c < 0
		}
		return tieBefore != nil && tieBefore(items[i], items[j])
	})
}

