package calibrate

import (
	"path/filepath"
	"reflect"
	"testing"
)

func TestTmpBadTimeSharedRule(t *testing.T) {
	clock := &fakeClock{t: mustDate(t, "2026-10-06")}
	path := filepath.Join(t.TempDir(), "ledger.json")
	l, err := openAt(path, clock.now)
	if err != nil {
		t.Fatal(err)
	}
	seedInstrument(t, l, "M-1")
	// usage: valid + two unparseable (raw text order: "aaa" < "zzz"), across instruments
	seedUsage(t, l,
		UsageRecord{InstrumentID: "M-2", RequestedAt: "zzz-bad", Reasons: []string{}},
		UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-06T02:00:00Z", Reasons: []string{}},
		UsageRecord{InstrumentID: "M-1", RequestedAt: "aaa-bad", Reasons: []string{}},
	)
	gotU := usageKeys(l.UsageRecords())
	wantU := [][2]string{
		{"M-1", "2026-10-06T02:00:00Z"},
		{"M-1", "aaa-bad"},
		{"M-2", "zzz-bad"},
	}
	if !reflect.DeepEqual(gotU, wantU) {
		t.Fatalf("usage bad-time order %v want %v", gotU, wantU)
	}
	// plans: valid then unparseable by raw text
	seedPlans(t, l,
		testPlan("PL-BAD2", "M-1", "zzz-bad", PlanStatusOpen),
		testPlan("PL-OK", "M-1", "2026-10-06T02:00:00Z", PlanStatusDone),
		testPlan("PL-BAD1", "M-1", "aaa-bad", PlanStatusOpen),
	)
	plans, _ := l.Plans("M-1")
	gotP := planNumbers(plans)
	wantP := []string{"PL-OK", "PL-BAD1", "PL-BAD2"}
	if !reflect.DeepEqual(gotP, wantP) {
		t.Fatalf("plan bad-time order %v want %v", gotP, wantP)
	}
}
EOF
go test ./calibrate/ -run TestTmpBadTimeSharedRule -v 2>&1 | tail -5
rm calibrate/zz_tmp_badtime_test.go
echo "removed temp test"
